#define N 1024
int arr[N][N];

// 1. Spatial Locality: Row-Major Access (Good)
// C/C++ arrays are row-major; accessing adjacently stored elements.
for (int i = 0; i < N; i++) {
    for (int j = 0; j < N; j++) {
        arr[i][j] = i + j; // High cache hit rate
    }
}

// 2. Spatial Locality: Column-Major Access (Poor)
// Large stride jumps, forcing new cache line loads often.
for (int j = 0; j < N; j++) {
    for (int i = 0; i < N; i++) {
        arr[i][j] *= 2; // Low cache hit rate (Cache thrashing)
    }
}

// 3. Temporal Locality
// 'sum' is repeatedly accessed and likely stays in L1 cache or registers.
long sum = 0;
int data[100];
for (int i = 0; i < 100; i++) {
    sum += data[i];
}
// 'sum' exhibits high temporal locality.
